from torch.utils.cpp_extension import load_inline

# Define the optimized CUDA kernel for matrix multiplication with shared memory
matmul_kernel_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define TILE_SIZE 16

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    // Shared memory for tiles of A and B
    __shared__ float tile_A[TILE_SIZE][TILE_SIZE];
    __shared__ float tile_B[TILE_SIZE][TILE_SIZE];

    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    float sum = 0.0f;

    // Loop over tiles
    for (int t = 0; t < N; t += TILE_SIZE) {
        // Load tiles into shared memory
        int t_row = t + threadIdx.y;
        int t_col = t + threadIdx.x;

        // Check bounds and load tile_A
        if (row < N && t_col < N) {
            tile_A[threadIdx.y][threadIdx.x] = A[row * N + t_col];
        } else {
            tile_A[threadIdx.y][threadIdx.x] = 0.0f;
        }

        // Check bounds and load tile_B
        if (t_row < N && col < N) {
            tile_B[threadIdx.y][threadIdx.x] = B[t_row * N + col];
        } else {
            tile_B[threadIdx.y][threadIdx.x] = 0.0f;
        }

        __syncthreads();

        // Compute partial product
        for (int k = 0; k < TILE_SIZE; k++) {
            sum += tile_A[threadIdx.y][k] * tile_B[k][threadIdx.x];
        }

        __syncthreads();
    }

    // Write result to global memory
    if (row < N && col < N) {
        C[row * N + col] = sum;
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    // Check dimensions
    TORCH_CHECK(A.dim() == 2, "A must be a 2D tensor");
    TORCH_CHECK(B.dim() == 2, "B must be a 2D tensor");
    int N = A.size(0);
    TORCH_CHECK(A.size(1) == N && B.size(0) == N && B.size(1) == N,
               "Both matrices must be square and of same size");

    auto C = torch::zeros({N, N}, A.options());

    // Configure kernel launch parameters
    dim3 threads(TILE_SIZE, TILE_SIZE);
    dim3 blocks((N + TILE_SIZE - 1) / TILE_SIZE, (N + TILE_SIZE - 1) / TILE_SIZE);

    // Launch kernel
    matmul_kernel<<<blocks, threads>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), N);

    return C;
}
"""

