        if (t_row < N && col < N) {
            tile_B[threadIdx.y][threadIdx.x] = B[t_row * N + col];
        } else {
            tile_B[threadIdx.y][threadIdx.x] = 0.0f;
        }

        __syncthreads();

        // Unrolled inner product loop
        for (int k = 0; k < TILE_SIZE; k += UNROLL_FACTOR) {
