import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define optimized CUDA kernel with register blocking
matmul_kernel_source = """
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define TILE_SIZE 16
#define REG_BLOCK_SIZE 2

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    __shared__ float tile_A[TILE_SIZE][TILE_SIZE];
    __shared__ float tile_B[TILE_SIZE][TILE_SIZE];

    // Each thread computes a REG_BLOCK_SIZE x REG_BLOCK_SIZE block of C
    float c_reg[REG_BLOCK_SIZE][REG_BLOCK_SIZE] = {{0}};

    int block_row = blockIdx.y * TILE_SIZE;
    int block_col = blockIdx.x * TILE_SIZE;

    int thread_row = threadIdx.y;
    int thread_col = threadIdx.x;

    // Loop over tiles
    for (int t = 0; t < N; t += TILE_SIZE) {
        // Load tile_A
        if (block_row + thread_row < N && t + thread_col < N) {
            tile_A[thread_row][thread_col] = A[(block_row + thread_row) * N + (t + thread_col)];
        } else {
            tile_A[thread_row][thread_col] = 0.0f;
        }

        // Load tile_B
        if (t + thread_row < N && block_col + thread_col < N) {
            tile_B[thread_row][thread_col] = B[(t + thread_row) * N + (block_col + thread_col)];
        } else {
            tile_B[thread_row][thread_col] = 0.0f;
        }

        __syncthreads();

        // Compute partial products
        for (int k = 0; k < TILE_SIZE; k++) {
            float a_val = tile_A[thread_row][k];

            for (int i = 0; i < REG_BLOCK_SIZE; i++) {
                float b_val = tile_B[k][thread_col * REG_BLOCK_SIZE + i];
                c_reg[0][i] += a_val * b_val;
            }
        }

        __syncthreads();
    }

    // Write results to global memory
    for (int i = 0; i < REG_BLOCK_SIZE; i++) {
        int row = block_row + thread_row;
        int col = block_col + thread_col * REG_BLOCK_SIZE + i;

        if (row < N && col < N) {
            C[row * N + col] = c_reg[0][i];
